import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import { myConsents, setConsent } from '../../common/sponsors';
/**
 * In the member's settings: every sponsor they share their email address
 * with, the sentence they agreed to, and "Stop sharing". Nothing at all when
 * they share with none.
 */
export default class ConsentList extends Component {
  consents = [];
  oninit(vnode) {
    super.oninit(vnode);
    myConsents().then(list => this.consents = list).catch(() => {
      /* app.request already showed the alert */
    }).finally(() => m.redraw());
  }
  view() {
    if (!this.consents.length) return null;
    const t = (key, params = {}) => app.translator.trans(`ernestdefoe-giveaways.forum.sponsors.${key}`, params);
    return m("fieldset", {
      className: "ConsentList"
    }, m("legend", null, t('settings_heading')), m("ul", {
      className: "ConsentList-items"
    }, this.consents.map(c => m("li", {
      className: "ConsentList-item"
    }, m("p", {
      className: "ConsentList-text"
    }, c.consent), m("p", {
      className: "helpText"
    }, t('settings_since', {
      date: dayjs(c.optedInAt).format('LL')
    })), m(Button, {
      className: "Button Button--sm",
      onclick: () => this.stop(c)
    }, t('stop_sharing'))))));
  }
  stop(c) {
    setConsent(c.campaign, c.campaignId, false).then(() => {
      this.consents = this.consents.filter(x => x !== c);
      app.alerts.show({
        type: 'success'
      }, app.translator.trans('ernestdefoe-giveaways.forum.sponsors.withdrawn', {
        sponsor: c.sponsor ?? ''
      }));
    }).catch(() => {
      /* app.request already showed the alert */
    }).finally(() => m.redraw());
  }
}
flarum.reg.add('ernestdefoe-giveaways', 'forum/sponsors/ConsentList', ConsentList);